cd /tmp/sv-38be17e498d74cc59323fe19aade1a25/moderate-version-conflicts && python3 -c "
import json
with open('baseline-packages.json') as f: b=json.load(f)
with open('after-cpm-packages.json') as f: a=json.load(f)

def extract(data):
    result={}
    for proj in data.get('projects',[]):
        name=proj['path'].rsplit('/',1)[-1] if '/' in proj['path'] else proj['path'].rsplit('\\\\',1)[-1]
        for fw in proj.get('frameworks',[]):
            for pkg in fw.get('topLevelPackages',[]):
                result.setdefault(name,{})[pkg['id']]=pkg.get('resolvedVersion',pkg.get('requestedVersion','?'))
    return result

bp=extract(b)
ap=extract(a)
print('BASELINE:')
for p,pkgs in sorted(bp.items()):
    for pkg,v in sorted(pkgs.items()):
        print(f'  {p}: {pkg} {v}')
print()
print('AFTER:')
for p,pkgs in sorted(ap.items()):
    for pkg,v in sorted(pkgs.items()):
        print(f'  {p}: {pkg} {v}')
" 2>&1

